select ('10000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid,'internal','Create test '||n,'00000000-0000-4000-8000-000000000051','00000000-0000-4000-8000-000000000051' from generate_series(1,20) n;
select has_function('public','create_license',array['uuid','text','timestamp with time zone','timestamp with time zone','uuid'],'exact create signature');
select function_returns('public','create_license',array['uuid','text','timestamp with time zone','timestamp with time zone','uuid'],'licenses','exact composite return');
select ok(p.prosecdef and p.provolatile='v' and p.proparallel='u' and p.proowner='postgres'::regrole and p.proconfig=array['search_path=pg_catalog'] and p.pronargdefaults=3 and l.lanname='plpgsql','exact function hardening and defaults') from pg_proc p join pg_language l on l.oid=p.prolang where p.oid='public.create_license(uuid,text,timestamptz,timestamptz,uuid)'::regprocedure;
select is(proargnames,array['p_tenant_id','p_plan_key','p_valid_from','p_valid_until','p_correlation_id'],'only authorized input names') from pg_proc where oid='public.create_license(uuid,text,timestamptz,timestamptz,uuid)'::regprocedure;
select ok(not has_function_privilege(r,'public.create_license(uuid,text,timestamptz,timestamptz,uuid)','EXECUTE'),r||' cannot execute') from unnest(array['public','anon','service_role'])r;
select ok(has_function_privilege('authenticated','public.create_license(uuid,text,timestamptz,timestamptz,uuid)','EXECUTE'),'authenticated entry only');
select is((select count(*)::integer from pg_proc p cross join lateral aclexplode(p.proacl)a where p.oid='public.create_license(uuid,text,timestamptz,timestamptz,uuid)'::regprocedure and a.grantee<>p.proowner and not(a.grantee='authenticated'::regrole and a.privilege_type='EXECUTE' and not a.is_grantable)),0,'exact nonowner ACL');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000051","aal":"aal1"}',true);
select throws_ok($q$select public.create_license('10000000-0000-4000-8000-000000000001','mini')$q$,'P0001','unauthorized','deny claim case 1');
